import wfdb, numpy as np, neurokit2 as nk
from scipy.signal import butter, filtfilt, medfilt

LEADS=['I','II','III','aVR','aVF','aVL','V1','V2','V3','V4','V5','V6']

def load(path):
    r=wfdb.rdrecord(path)
    sig=r.p_signal.copy()
    sig=np.nan_to_num(sig)
    idx={n:i for i,n in enumerate(r.sig_name)}
    return sig, r.fs, idx

def bp(sig, fs, lo=0.5, hi=40):
    b,a=butter(3,[lo/(fs/2),hi/(fs/2)],btype='band')
    return filtfilt(b,a,sig,axis=0)

def rpeaks(sig, fs, idx):
    # use lead with best SNR among II, V1..V6, I
    cands=['II','I','V2','V5','V1','V4']
    best=None
    for c in cands:
        x=sig[:,idx[c]]
        try:
            _,info=nk.ecg_peaks(x, sampling_rate=fs, method='neurokit')
            pk=info['ECG_R_Peaks']
        except Exception:
            continue
        if len(pk)<3: continue
        rr=np.diff(pk)
        score=len(pk)
        if best is None or len(pk)>len(best[1]):
            best=(c,pk)
    return best

def vm(sig, idx, leads=('I','II','V1','V2','V3','V4','V5','V6')):
    m=np.stack([sig[:,idx[l]] for l in leads],axis=1)
    return np.sqrt((m**2).sum(axis=1))
EOF
