import json, base64, collections, datetime as dt

D='/tmp/w/'
EVAL=dt.datetime.fromisoformat('2026-09-24T12:00:00-04:00')

def load(t):
    return [json.loads(l) for l in open(D+t+'.ndjson')]

MEDS={}
for m in load('Medication'):
    name=None
    for i in m.get('identifier',[]):
        if i['system'].endswith('mimic-medication-name'): name=i['value']
    if not name:
        c=m.get('code',{})
        name=c.get('text') or c.get('coding',[{}])[0].get('code')
    MEDS[m['id']]=name

def mname(r):
    if 'medicationReference' in r:
        return MEDS.get(r['medicationReference']['reference'].split('/')[-1],'?')
    cc=r.get('medicationCodeableConcept',{})
    if cc.get('text'): return cc['text']
    return cc.get('coding',[{}])[0].get('code','?')

def pid(r):
    for k in ('subject','patient'):
        if k in r: return r[k]['reference'].split('/')[-1]
    return None

def note_text(d):
    return base64.b64decode(d['content'][0]['attachment']['data']).decode('utf-8','replace')

def role(d):
    for e in d.get('extension',[]):
        if e['url'].endswith('author-role'): return e.get('valueCode')
    return None

PATIENTS={p['id']:p for p in json.load(open(D+'patients.json'))['resources']}
def age(p, at=EVAL):
    b=dt.date.fromisoformat(p['birthDate'])
    a=at.date()
    return a.year-b.year-((a.month,a.day)<(b.month,b.day))
