import sys;sys.path.insert(0,'/tmp/w/an')
from common import *
import pickle, collections
P=pickle.load(open(D+'pat.pkl','rb'))
enc={e['id']:e for e in load('Encounter')}
def edate(ref):
    if not ref: return ''
    e=enc.get(ref.split('/')[-1]); 
    return (e or {}).get('period',{}).get('start','') if e else ''

def dossier(p, notes_since='2025-01-01', obs_since='2025-06-01'):
    d=P[p]; pat=PATIENTS[p]
    L=[]
    L.append(f"PATIENT {p} | {pat['gender']} | dob {pat['birthDate']} | age {age(pat)} | deceased {pat.get('deceasedDateTime','-')}")
    # conditions dedup with latest date
    cc={}
    for c in d.get('cond',[]):
        dt_=edate(c.get('encounter',{}).get('reference'))
        for x in c['code']['coding']:
            key=x.get('display') or x.get('code')
            cc.setdefault(key,[]).append((dt_,c['id']))
    L.append("CONDITIONS:")
    for k,v in sorted(cc.items(), key=lambda kv:max(x[0] for x in kv[1]), reverse=True):
        ds=sorted(set(x[0][:10] for x in v))
        L.append(f"  {k} [{ds[0]}..{ds[-1]}] n={len(v)} id={v[-1][1]}")
    L.append("CLINIC MED ORDERS (2025+, with validity):")
    for r in sorted(d.get('mr',[]), key=lambda r:r.get('authoredOn','')):
        if r.get('authoredOn','')<'2025-01-01': continue
        vp=r.get('dispenseRequest',{}).get('validityPeriod',{})
        L.append(f"  {r.get('authoredOn','')[:16]} {mname(r)} | {r.get('dosageInstruction',[{}])[0].get('text','')} | {r['status']} | valid {vp.get('start','')[:10]}..{vp.get('end','')[:10]} | id={r['id']}")
    L.append("PROCEDURES (2024+):")
    for r in sorted(d.get('proc',[]), key=lambda r:r.get('performedDateTime','') or r.get('performedPeriod',{}).get('start','')):
        t=(r.get('performedDateTime') or r.get('performedPeriod',{}).get('start') or '')
        if t<'2024-01-01': continue
        L.append(f"  {t[:10]} {r['code']['coding'][0].get('display')} id={r['id']}")
    L.append("LABS (K/Mg/INR) since "+obs_since+":")
    for o in sorted(d.get('obs',[]), key=lambda o:o.get('effectiveDateTime','')):
        t=o.get('effectiveDateTime','')
        if t<obs_since: continue
        v=o.get('valueQuantity',{})
        L.append(f"  {t[:16]} {o['code']['coding'][0].get('display')} = {v.get('value')} {v.get('unit','')} id={o['id']}")
    L.append("ECGS:")
    for e in sorted(d.get('ecg',[]), key=lambda e:e['time']):
        L.append(f"  {e['time']} ecg={e['ecg']}")
    L.append("NOTES since "+notes_since+":")
    for x in sorted(d.get('docs',[]), key=lambda x:x['date']):
        if x['date']<notes_since: continue
        L.append(f"--- {x['date'][:16]} [{role(x)}] {x['type']['coding'][0]['display']} id={x['id']}")
        L.append(note_text(x))
    return '\n'.join(L)

if __name__=='__main__':
    import sys
    for p in sys.argv[1:]:
        print(dossier(p)); print('#'*100)
EOF
